#include <stdint.h>
#include "mygpio.h"


int main(void)
{
	GPIO_init(GPIOA, 0, GPIO_PIN_INPUT);
	GPIO_init(GPIOD, 15, GPIO_PIN_OUTPUT);
	GPIO_init(GPIOD, 14, GPIO_PIN_OUTPUT);
    /* Loop forever */
	for(;;){
		if(GPIO_PIN_READ(GPIOA, GPIO_PIN_INPUT)){
			GPIO_PIN_WRITE(GPIOD, 15, GPIO_PIN_SET);
			GPIO_PIN_WRITE(GPIOD, 14, GPIO_PIN_SET);
		}
		else{
			GPIO_PIN_WRITE(GPIOD, 15, GPIO_PIN_RESET);
			GPIO_PIN_WRITE(GPIOD, 14, GPIO_PIN_RESET);
		}
	}
}
